 {n:'平',full:'平气',rate:16,amp:1,inh:.42},{n:'深',full:'深息',rate:8,amp:1.26,inh:.46},{n:'浅',full:'浅息',rate:22,amp:.5,inh:.4},{n:'粗',full:'气粗',rate:20,amp:1.18,inh:.38},{n:'微',full:'少气',rate:12,amp:.3,inh:.42},{n:'喘',full:'喘促',rate:28,amp:.85,inh:.32,rough:.22},{n:'哮',full:'哮鸣',rate:20,amp:.8,inh:.22},{n:'短',full:'短气',rate:32,amp:.55,inh:.3},{n:'叹',full:'太息',rate:14,amp:.95,inh:.4,sigh:{amp:1.7,len:1.45}}
