const RHYTHM_META={heart:{name:'心跳 · 双峰',color:'#d4706a',hint:'主峰推开内层，次峰沿外缘回响',unit:'BPM'},breath:{name:'呼吸',color:'#6ad4c8',hint:'吸入与呼出共享同一张力曲线',unit:'次/分'},pulse:{name:'脉象',color:'#d4af6a',hint:'起伏、空拍与迟数形成不同脉络',unit:'次/分'},gait:{name:'步态 · 交替',color:'#9a8ad4',hint:'左右落点交替，保留离地的空隙',unit:'步/分'},tide:{name:'潮汐 · 长波',color:'#6aaed4',hint:'潮来急、潮退缓，余涟向外扩散',unit:'涌/分'},fire:{name:'萤火 · 双闪',color:'#f0cf8e',hint:'两次亮起成组，暗歇仍留余光',unit:'组/分'}};
function rhythmShape(x,sh={}){const rise=sh.rise||.11,sus=sh.sustain||0,dec=sh.decay||.5;let v=0;if(x<rise){const u=x/rise;v=sh.round?u*u*(3-2*u):Math.pow(u,.65)}else if(x<rise+sus)v=1;else{const u=(x-rise-sus)/dec;if(u>=0&&u<1){v=1-u;if(sh.hollow)v*=1-.8*Math.exp(-Math.pow((u-.3)/.13,2));else v+=.15*Math.exp(-Math.pow((u-.42)/.15,2));v=Math.max(0,v)}}if(sh.tremor)v*=1-sh.tremor/2+sh.tremor*Math.abs(Math.sin(x*44));if(sh.rough)v*=Math.max(.3,1+sh.rough*.6*(Math.sin(x*29)*.6+Math.sin(x*53+1.3)*.4));return v}
function pulseCycle(p){const D=60/p.rate,ev=[];if(p.scat){const jit=[0,.35,-.2,.5,-.3,.25,-.15],amps=[.7,.3,.9,.2,.55,.35,.18];let t=0;for(let i=0;i<7;i++){ev.push({t,a:p.amp*amps[i]});t+=D*(1+jit[i])}const C=t+D*.5;return{C,wave:tm=>{let v=0;for(const e of ev){const x=(tm-e.t)/D;if(x>=0&&x<1)v+=e.a*rhythmShape(x,p.sh)}return v}}}if(p.skip)for(let i=0;i<p.skip.c;i++)if(!p.skip.s.includes(i))ev.push({t:i*D,a:p.amp});else for(let i=0;i<4;i++)ev.push({t:i*D,a:p.amp});const C=(p.skip?p.skip.c:4)*D;return{C,wave:tm=>{let v=0;for(const e of ev){const x=(tm-e.t)/D;if(x>=0&&x<1)v+=e.a*rhythmShape(x,p.sh)}return v}}}
function breathCycle(b,rate){const D=60/rate,ev=[],amps=b.sigh?[1,1,1,b.sigh.amp]:[1,1,1,1],lens=b.sigh?[1,1,1,b.sigh.len]:[1,1,1,1];let t=0;for(let i=0;i<amps.length;i++){ev.push({t,d:D*lens[i],a:b.amp*amps[i]});t+=D*lens[i]}const C=t;return{C,wave:tm=>{let v=0;for(const e of ev){const x=(tm-e.t)/e.d;if(x>=0&&x<1){const q=b.inh||.4;let s=x<q?Math.sin(x/q*Math.PI/2):Math.cos((x-q)/(1-q)*Math.PI/2);if(b.rough)s*=1-b.rough/2+b.rough*Math.abs(Math.sin(x*26));v+=e.a*s}}return v}}}
function simpleRhythm(mode,rate){const D=60/rate;if(mode==='heart')return{C:D,wave(tm){const x=tm/D;return Math.exp(-Math.pow((x-.1)/.045,2))+.58*Math.exp(-Math.pow((x-.32)/.065,2))}};if(mode==='gait'){const amps=[1.1,.88,1.1,.88],ev=amps.map((a,i)=>({t:i*D,a})),C=4*D;return{C,wave:tm=>{let v=0;for(const e of ev){const x=(tm-e.t)/D;if(x>=0&&x<1)v+=e.a*rhythmShape(x,{rise:.07,decay:.36})}return v}}}if(mode==='tide'){const C=D;return{C,wave(tm){const x=tm/C,p=.3;let v=x<p?Math.sin(x/p*Math.PI/2):Math.cos((x-p)/(1-p)*Math.PI/2);if(x>=p)v+=.1*Math.sin((x-p)/(1-p)*Math.PI*3)*(1-x);return Math.max(0,v*1.2)}}}const C=D,fd=Math.min(.55,C*.16),ev=[{t:0,a:1.3},{t:fd*1.5,a:.95}];return{C,wave:tm=>{let v=0;for(const e of ev){const x=(tm-e.t)/fd;if(x>=0&&x<1)v+=e.a*rhythmShape(x,{rise:.2,decay:.6,round:1})}return v}}}
